export function findProductsNoContract(items, id) {
  return items.find((item) => item.id === id) ?? null;
}

// Form text -> the types the API expects (taken from the example request body).
export function toProductsNoContractInput(values) {
  return {
    name: String(values.name ?? "").trim(),
    price: String(values.price ?? "").trim(),
    stock: String(values.stock ?? "").trim(),
  };
}

// Raw values to prefill the form when an item is selected.
export function toFormValues(item) {
  if (!item) return {};
  return {
    name: item.name,
    price: item.price,
    stock: item.stock,
  };
}
